mapper.select:
select e.*, s.name studentName ,c.name courseName
from enrollment e
left join student s on e.student_id = s.id
left join course c on e.course_id = c.id

    e.semester like concat('%',#{semester},'%')
    and e.student_id = #{studentId} 
    and e.course_id = #{courseId} 
    and e.grade between #{gradeMin} and #{gradeMax}

order by e.student_id desc

mapper.update:
UPDATE enrollment

        student_id = #{studentId},
        course_id = #{courseId},
        grade = #{grade},
        semester = #{semester}

WHERE id = #{id}
